        let headers
        if (typeof reqHeaders === 'string') headers = Request[kHTTP2CopyHeaders](reqHeaders.trim())
        else headers = reqHeaders

        if (upgrade) {
          errorRequest(client, request, new Error('Upgrade not supported for H2'))
          return false
        }

